@dataclass(frozen=True)
class RelevanceRecord:
    """Проверенная запись синтетического источника для двух адресов запроса."""
    source: IPv4Address
    destination: IPv4Address
    pairs: tuple[RelevantAclPair, ...] = ()


@dataclass(frozen=True)
class ValidatedSyntheticEvidence:
    """Локальные данные одного вызова с сохранением порядка записей и снимков."""
    relevance_records: tuple[RelevanceRecord, ...] = ()
    snapshots: tuple[AclSnapshot, ...] = ()


@dataclass(frozen=True)
class ValidatedInput:
    """Полностью проверенные поток и предоставленные синтетические данные."""
    flow: IPv4Flow
