from __future__ import annotations

from dataclasses import dataclass
from ipaddress import IPv4Address
from typing import TYPE_CHECKING, Literal

if TYPE_CHECKING:
    # Interface designer добавит импорты ReportGroup, RelevantAclPair,
    # AclSnapshot, RequestFailure и ValidatedInput из областей-владельцев.
    pass


@dataclass(frozen=True)
class CliObservation:
    """Наблюдаемые результаты изолированного запуска публичной CLI."""
    stdout: str
    stderr: str
    exit_code: int


@dataclass(frozen=True)
class SourceCall:
    """Аргументы одного вызова подставленного источника в порядке наблюдения."""
    operation: Literal['relevance', 'snapshot']
    arguments: tuple[IPv4Address | str, ...] = ()


@dataclass(frozen=True)
class MatchingContractObservation:
    """Результаты чистого сопоставления и полностью завершённого check."""
    match_results: tuple[bool, ...] = ()
    report_groups: tuple[ReportGroup, ...] = ()
    source_calls: tuple[SourceCall, ...] = ()


@dataclass(frozen=True)
class InputContractObservation:
    """Принятие или отказ вместе с байтами фикстуры до и после проверки."""
    outcome: ValidatedInput | RequestFailure
    fixture_before: bytes
    fixture_after: bytes


@dataclass(frozen=True)
class SourceContractObservation:
    """Наблюдения источников; полученные данные при отказе не являются отчётом."""
    relevance: tuple[RelevantAclPair, ...] = ()
    snapshots: tuple[AclSnapshot, ...] = ()
    failure: RequestFailure | None = None


@dataclass(frozen=True)
class PythonSourceEvidence:
    """Текст Python-модуля для независимой проверки AST и импортов."""
    module_path: str
    source_text: str
